import numpy as np
from math import gcd

def units(Q): return [a for a in range(Q) if a % 3 != 0]

def build_par(Q, s, kchar):
    U = units(Q); phi = len(U); idx = {a:i for i,a in enumerate(U)}
    dlog = {}; p = 1
    for j in range(phi): dlog[p] = j; p = (p*2) % Q
    inv = {a: pow(a, -1, Q) for a in U}
    chi = {a: np.exp(2j*np.pi*kchar*dlog[a]/phi) for a in U}
    n = 2*phi
    M = np.zeros((n,n), complex)
    den = 1.0 - 2.0**(-(1+s)*phi)
    for a in U:
        t = (3*a+1) % Q
        for ap in U:
            b0 = dlog[(t*inv[ap]) % Q] % phi
            if b0 == 0: b0 = phi
            W = (3.0**s) * 2.0**(-(1+s)*b0) / den
            for tau in (0,1):
                M[idx[ap]*2+(tau+b0)%2, idx[a]*2+tau] += W * chi[a]
    return M

def rho(M): return max(abs(np.linalg.eigvals(M)))

def cond_exp(k, r):
    """conductor exponent c of chi_k at level 3^r: 3^{r-c} || k (k=0 -> c=0)."""
    if k == 0: return 0
    v = 0; kk = k
    while kk % 3 == 0: kk //= 3; v += 1
    return r - v

print("=== gamma_c by conductor, residue x parity (collapse check: equal across r) ===")
for s in (0.0, 1.0):
    print(f"--- s={s:.0f} ---")
    for r,Q in ((2,9),(3,27),(4,81),(5,243)):
        phi = len(units(Q))
        r0 = rho(build_par(Q,s,0))
        byc = {}
        for k in range(1, phi//2+1):
            c = cond_exp(k, r)
            v = rho(build_par(Q,s,k))/r0
            if c not in byc or v > byc[c][0]: byc[c] = (v,k)
        out = "  ".join(f"c={c}:{byc[c][0]:.6f}(k={byc[c][1]})" for c in sorted(byc))
        print(f"Q={Q:4d}: {out}")
